fn is_palindrome(text: Vec<char>) -> bool {
    fn ascii_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe because 'A'..='Z' are ASCII and map 1-to-1 to 'a'..='z'
            ((c as u8) + (b'a' - b'A')) as char
        } else {
            c
        }
    }

    let n = text.len();
    let mut i = 0usize;

    while i < n / 2 {
        if ascii_lower(text[i]) != ascii_lower(text[n - 1 - i]) {
            return false;
        }
        i += 1;
    }

    true
}